SELECT medpayment1_1.hcpcs_code AS hcpcs_code,   medpayment1_1.hcpcs_description AS hcpcs_description,   medpayment1_1.nppes_provider_state AS nppes_provider_state,   SUM((CAST(medpayment1_1.average_medicare_payment_amt AS double precision) * CAST(CAST(medpayment1_1.number_of_records AS BIGINT) AS double precision))) AS sum_calculation_0820513143749095_ok,   SUM(medpayment1_1.average_submitted_chrg_amt) AS sum_average_submitted_chrg_amt_ok FROM medpayment1_1 WHERE ((medpayment1_1.hcpcs_code = '27447') AND (medpayment1_1.hcpcs_description = 'Total knee arthroplasty')) GROUP BY medpayment1_1.hcpcs_code,   medpayment1_1.hcpcs_description, medpayment1_1.nppes_provider_state;
